// Captures what the Admin profile banner and profile character write routes put on the wire and leave in the
// database, by running the real Admin Route Handlers (apps/admin/src/app/api/profile-banners, profile-characters)
// and the real @rotra/db services (Prisma) against a throwaway local Postgres. The harness is
// capture-writes-base.mjs; the Go side is apps/api/internal/writetest. Group:
//   profiles   PATCH and DELETE /api/profile-banners/{id}, POST .../restore, POST .../default,
//              PATCH and DELETE /api/profile-characters/{id}, POST .../restore
// The two upload routes (POST /api/profile-banners, POST /api/profile-characters) send a picture to Supabase
// Storage, so the pictures track owns them and they are not captured.
//
//   docker run -d --rm --name rotra-capture-pg -e POSTGRES_PASSWORD=test -p 127.0.0.1:55443:5432 postgres:16-alpine
//   source ~/.nvm/nvm.sh && nvm use
//   ROTRA_CAPTURE_DB_URL=postgres://postgres:test@127.0.0.1:55443/postgres \
//     node node_modules/.pnpm/vitest@*/node_modules/vitest/vitest.mjs run --config apps/api/testdata/tools/vitest.capture.config.mjs apps/api/testdata/tools/capture-writes-profiles.test.mjs
//
// Refuses any host but 127.0.0.1/localhost. It creates its own database (rotra_capture_<n>) and drops it.
// The cases and the seed are generated by gen-writes-admin-profiles-cases.py. Output:
// apps/api/internal/adminwrites/testdata/profiles.golden.json.
//
// Only the Supabase session check is replaced: verifySubject answers the step's subject (a step with none is signed
// out), so loadAccountContext (the active-admin check) and every service run for real.
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { afterAll, beforeAll, test, vi } from 'vitest'
import { captureWrites, openCaptureDb, root } from './capture-writes-base.mjs'

vi.mock('../../../../packages/db/src/auth/supabase.ts', async (importOriginal) => ({
  ...(await importOriginal()),
  verifySubject: async () => {
    const { currentSubject } = await import('./capture-writes-base.mjs')
    const subject = currentSubject()
    return subject ? { provider: 'supabase', subject } : null
  },
}))

const here = dirname(fileURLToPath(import.meta.url))
const testdata = resolve(here, '../../internal/adminwrites/testdata')
const apiDir = resolve(root, 'apps/admin/src/app/api')

let capture
beforeAll(async () => {
  capture = await openCaptureDb()
})
afterAll(async () => {
  await capture?.close()
})

test('profiles', async () => {
  await captureWrites({ db: capture.db, testdata, name: 'profiles', apiDir })
})
